{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Test mild positive training-frequency scaling of history inputs across all four datasets. Counts use training interactions only; checkpointed scales ensure identical inference through the generated predictor's imported model class. Learned embeddings, GRU topology, readout, candidate scoring, loss and optimizer remain unchanged.",
      "edits": [
        {
          "find": "DATA_DIR = os.environ.get(\"GAGC_DATA_DIR\", \"./input/trainval\")",
          "replace": "DATA_DIR = os.environ['GAGC_DATA_DIR']"
        },
        {
          "find": "        self.item_emb = UnitNormItemEmbedding(itemnum + 1, hidden_units, padding_idx=0)\n        dropout = dropout_rate if num_layers > 1 else 0.0",
          "replace": "        self.item_emb = UnitNormItemEmbedding(itemnum + 1, hidden_units, padding_idx=0)\n        self.register_buffer(\"history_frequency_scale\", torch.ones(itemnum + 1))\n        self.history_frequency_scale[0] = 0.0\n        dropout = dropout_rate if num_layers > 1 else 0.0"
        },
        {
          "find": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(\n            self.item_emb(seq) * self.history_frequency_scale[seq].unsqueeze(-1)\n        )"
        },
        {
          "find": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(\n            self.item_emb(seq) * self.history_frequency_scale[seq].unsqueeze(-1)\n        )"
        },
        {
          "find": "    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)",
          "replace": "    training_counts = np.zeros(itemnum + 1, dtype=np.int64)\n    for items in user_train.values():\n        np.add.at(training_counts, np.asarray(items, dtype=np.int64), 1)\n    positive_counts = training_counts[1:][training_counts[1:] > 0]\n    median_count = float(np.median(positive_counts)) if positive_counts.size else 1.0\n    frequency_scale = np.clip(\n        (np.maximum(training_counts, 1).astype(np.float64) / median_count) ** 0.10,\n        0.9, 1.1,\n    ).astype(np.float32)\n    frequency_scale[0] = 0.0\n    with torch.no_grad():\n        model.history_frequency_scale.copy_(\n            torch.as_tensor(frequency_scale, device=device)\n        )\n    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)"
        }
      ]
    }
  ],
  "change_summary": "Apply bounded positive training-frequency features to history embeddings for every category's single GRU4Rec model. Scales are saved in model checkpoints and restored by the existing generated predictor."
}
